import { Human } from '@vladmandic/human';

const human = new Human();

async function getFaceEmbeddings(image, options = {}) {
    const {
        maxFaces = 100,      // Detect up to 100 faces
        minConfidence = 0.5  // Adjust if you want stricter detection
    } = options;

    // Configure Human for multi-face detection + embedding extraction
    const config = {
        detector: {
            maxDetected: maxFaces,
            minConfidence: minConfidence,
        },
        face: {
            description: { enabled: true } // This enables embeddings
        }
    };

    try {
        const result = await human.process(image, config);
        const faces = result.face || [];
        // Extract embeddings (they are Float32Arrays, but we convert to plain arrays for easy JSON)
        const embeddings = faces.map(face => Array.from(face.embedding));
        return embeddings;
    } catch (error) {
        console.error('Face embedding error:', error);
        throw new Error(`Failed to process image: ${error.message}`);
    }
}

